"""Substreams Python sink example.

Streams a Substreams module over gRPC, persists the cursor after each handled
block and transparently reconnects (resuming from the persisted cursor).
"""

import argparse
import os
import random
import re
import sys
import time
from datetime import datetime, timezone
from pathlib import Path

# Protobuf/gRPC code is generated by `buf generate` in ./gen (see README.md)
sys.path.insert(0, str(Path(__file__).parent / "gen"))

import grpc
import requests

from sf.substreams.rpc.v2 import service_pb2 as rpc_v2
from sf.substreams.rpc.v3 import service_pb2 as rpc_v3
from sf.substreams.rpc.v4 import service_pb2 as rpc_v4
from sf.substreams.rpc.v4 import service_pb2_grpc as rpc_v4_grpc
from sf.substreams.v1 import package_pb2

REGISTRY_URL = "https://spkg.io"

DEFAULT_SPKG = "ethereum_common@v0.4.0"
DEFAULT_MODULE = "filtered_events"

PACKAGE_NAME_RE = re.compile(r"^[a-zA-Z][a-zA-Z0-9_-]{0,63}$")
VERSION_RE = re.compile(r"^v?\d+\.\d+\.\d+(-[0-9A-Za-z.-]+)?(\+[0-9A-Za-z.-]+)?$")

BACKOFF_INITIAL = 0.5
BACKOFF_MAX = 45.0

MAX_MESSAGE_SIZE = 100 * 1024 * 1024

# Status codes for which retrying is pointless
FATAL_CODES = {
    grpc.StatusCode.UNAUTHENTICATED,
    grpc.StatusCode.PERMISSION_DENIED,
    grpc.StatusCode.INVALID_ARGUMENT,
}


def log(message: str) -> None:
    print(f"{datetime.now(timezone.utc).isoformat()} {message}", flush=True)


# --------------------------------------------------------------------------
# Package loading
# --------------------------------------------------------------------------


def registry_url(value: str) -> str | None:
    """Returns the spkg.io URL when `value` is a `name[@version]` reference, else None."""
    parts = value.split("@")
    if len(parts) > 2 or not PACKAGE_NAME_RE.match(parts[0]):
        return None

    version = parts[1] if len(parts) == 2 else ""
    if version in ("", "latest"):
        return f"{REGISTRY_URL}/v1/packages/{parts[0]}/latest"

    if not VERSION_RE.match(version):
        raise ValueError(f"version '{version}' is not valid Semver format")

    return f"{REGISTRY_URL}/v1/packages/{parts[0]}/{version}"


def read_package(value: str) -> package_pb2.Package:
    url = registry_url(value)
    if url is None and value.startswith("http"):
        url = value

    if url is not None:
        response = requests.get(url, timeout=60)
        response.raise_for_status()
        content = response.content
    else:
        content = Path(value).read_bytes()

    package = package_pb2.Package()
    package.ParseFromString(content)
    return package


def parse_params(value: str) -> list[tuple[str, str]]:
    """Parses `<module>:<expr>[,<module>:<expr>...]`."""
    if not value.strip():
        raise ValueError("wrong --params input value: empty string")

    params = []
    for entry in value.split(","):
        module, sep, expression = entry.partition(":")
        if not sep:
            raise ValueError(f"wrong --params value for '{entry}': missing ':' delimiter")
        params.append((module.strip(), expression.strip()))

    return params


def apply_params(package: package_pb2.Package, params: list[tuple[str, str]]) -> None:
    """Replaces the params input (always the first input) of each module named in `params`."""
    for name, expression in params:
        for module in package.modules.modules:
            if module.name == name and len(module.inputs) > 0:
                module.inputs[0].params.value = expression


def find_module(package: package_pb2.Package, name: str):
    for module in package.modules.modules:
        if module.name == name:
            return module

    raise ValueError(f"module '{name}' not found in package")


def parse_block_range(value: str, initial_block: int) -> tuple[int, int]:
    """Accepts `<start>:<stop>`, `<start>:`, `:<stop>` or `<stop>`.

    Either side can be relative (`+N`), a negative start is relative to chain head,
    an empty start is the module's initial block and a stop of 0 means "forever".
    """
    prefix, sep, suffix = value.partition(":")
    if not sep:
        prefix, suffix = "", value

    def to_int(text: str, name: str) -> int:
        try:
            return int(text)
        except ValueError:
            raise ValueError(f"argument <{name}> is not a valid integer: '{text}'") from None

    if prefix == "":
        start = initial_block
    elif prefix.startswith("+"):
        start = initial_block + to_int(prefix[1:], "start")
    else:
        start = to_int(prefix, "start")

    if suffix in ("", "-"):
        stop = 0
    elif suffix.startswith("+"):
        stop = start + to_int(suffix[1:], "stop")
    else:
        stop = to_int(suffix, "stop")

    return start, stop


# --------------------------------------------------------------------------
# Cursor persistence
# --------------------------------------------------------------------------


def load_cursor(path: Path) -> str:
    # FIXME: A local file is only suitable for demo purposes. In production, save the
    # cursor in your database, in the same transaction as the data it corresponds to.
    try:
        return path.read_text().strip()
    except FileNotFoundError:
        return ""


def persist_cursor(path: Path, cursor: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(path.suffix + ".tmp")
    tmp.write_text(cursor)
    os.replace(tmp, path)  # atomic replacement


# --------------------------------------------------------------------------
# Block handling
# --------------------------------------------------------------------------


def handle_block(data: rpc_v2.BlockScopedData) -> None:
    output = data.output.map_output

    # To decode the actual `Any` received, generate the Python code of your module's
    # Protobuf types (see README.md) and use:
    #
    #     events = my_pb2.Events()
    #     output.Unpack(events)
    clock = data.clock
    drift = datetime.now(timezone.utc) - clock.timestamp.ToDatetime(tzinfo=timezone.utc)

    log(
        f"Block #{clock.number} final={clock.number <= data.final_block_height} - "
        f"Payload {output.type_url.removeprefix('type.googleapis.com/')} "
        f"({len(output.value)} bytes) - Drift {int(drift.total_seconds())}s"
    )


def handle_undo(signal: rpc_v2.BlockUndoSignal) -> None:
    # `BlockUndoSignal` must be treated as "delete every data that has been recorded after
    # block height specified by `last_valid_block`". If for example all your added records
    # contain a block number, a simple way is to do
    # `delete all records where block_num > last_valid_block.number` (this is true for
    # append only records, so when only `INSERT` are allowed).
    raise NotImplementedError(
        "you must implement some kind of block undo handling, or use --final-blocks-only "
        f"(last valid block is #{signal.last_valid_block.number})"
    )


# --------------------------------------------------------------------------
# Streaming
# --------------------------------------------------------------------------


def consume(args, package, start: int, stop: int, cursor_path: Path, cursor: str) -> None:
    """Runs one connection, returns when the server closed the stream cleanly (stop block reached)
    and raises `grpc.RpcError` on any stream failure."""
    request = rpc_v3.Request(
        start_block_num=start,
        start_cursor=cursor,
        stop_block_num=stop,
        final_blocks_only=args.final_blocks_only,
        production_mode=True,
        output_module=args.module,
        package=package,
        progress_messages_interval_ms=30_000,
    )

    endpoint = args.endpoint
    insecure = endpoint.startswith("http://")
    endpoint = endpoint.removeprefix("https://").removeprefix("http://").rstrip("/")
    if ":" not in endpoint:
        endpoint += ":80" if insecure else ":443"

    options = [
        ("grpc.max_receive_message_length", MAX_MESSAGE_SIZE),
        ("grpc.max_send_message_length", MAX_MESSAGE_SIZE),
    ]
    if insecure:
        channel = grpc.insecure_channel(endpoint, options=options)
    else:
        channel = grpc.secure_channel(endpoint, grpc.ssl_channel_credentials(), options=options)

    metadata = [("x-api-key", args.api_key)]

    with channel:
        stub = rpc_v4_grpc.StreamStub(channel)
        stream = stub.Blocks(request, metadata=metadata, compression=grpc.Compression.Gzip)

        for response in stream:
            kind = response.WhichOneof("message")
            if kind == "session":
                log(
                    f"CONNECTED trace_id={response.session.trace_id} "
                    f"resolved_start_block={response.session.resolved_start_block}"
                )
            elif kind == "block_scoped_datas":
                for data in response.block_scoped_datas.items:
                    handle_block(data)
                    # Persist only once the block has been fully handled
                    persist_cursor(cursor_path, data.cursor)
            elif kind == "block_undo_signal":
                signal = response.block_undo_signal
                log(f"UNDO last_valid_block=#{signal.last_valid_block.number}")
                handle_undo(signal)
                persist_cursor(cursor_path, signal.last_valid_cursor)
            elif kind == "progress":
                log(f"PROGRESS running_jobs={len(response.progress.running_jobs)}")
            elif kind == "fatal_error":
                log(f"FATAL_ERROR message from server: {response.fatal_error.reason}")


def run(args, package, start: int, stop: int) -> None:
    cursor_path = Path(args.cursor_file)
    cursor = load_cursor(cursor_path)
    backoff = BACKOFF_INITIAL

    attempt = 0
    while True:
        attempt += 1
        log(
            f"CONNECT attempt={attempt} endpoint={args.endpoint} start_block={start} stop_block={stop} "
            f"final_blocks_only={args.final_blocks_only} cursor={'<resume>' if cursor else '<none>'}"
        )

        previous = cursor
        try:
            consume(args, package, start, stop, cursor_path, cursor)
            log("STREAM completed, reached stop block")
            return
        except grpc.RpcError as err:
            code = err.code()
            if code in FATAL_CODES:
                raise SystemExit(f"fatal gRPC error {code.name}: {err.details()}") from err

            reason = f"grpc status {code.name}: {err.details()}"
            # The persisted cursor is the source of truth for what was fully handled
            cursor = load_cursor(cursor_path)

        if cursor != previous:
            backoff = BACKOFF_INITIAL  # healthy progress was made

        sleep = backoff * random.uniform(0.8, 1.2)
        log(f'RECONNECT reason="{reason}" backoff={int(sleep * 1000)}ms')
        time.sleep(sleep)
        backoff = min(backoff * 2, BACKOFF_MAX)


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        usage="%(prog)s <endpoint> [<spkg> [<module> [<start>:<stop>]]] [flags]",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        description=(
            "<endpoint> is `host:port` or `http(s)://host:port` (TLS by default), also read from\n"
            "SUBSTREAMS_ENDPOINT when omitted.\n"
            "<spkg> is a local file, a full URL or `spkg_package@version`.\n"
            "<start>:<stop> is the block range, `-1:` is current head and onwards forever.\n"
            "\n"
            "The environment variable SUBSTREAMS_API_KEY must be set and contain a valid API key."
        ),
        epilog=(
            "examples:\n"
            f"  python main.py mainnet.eth.streamingfast.io:443 {DEFAULT_SPKG} {DEFAULT_MODULE} 21000000:+10\n"
            f"  python main.py mainnet.eth.streamingfast.io:443 {DEFAULT_SPKG} {DEFAULT_MODULE} -1: "
            "--final-blocks-only"
        ),
    )
    parser.add_argument("endpoint", nargs="?", default=os.getenv("SUBSTREAMS_ENDPOINT"))
    parser.add_argument("spkg", nargs="?", default=DEFAULT_SPKG)
    parser.add_argument("module", nargs="?", default=DEFAULT_MODULE)
    parser.add_argument("block_range", nargs="?", default="", metavar="start:stop")
    parser.add_argument(
        "--params",
        metavar="<module>:<expr>[,...]",
        help="module parameters, e.g. --params=filtered_events:'(type:transfer)'",
    )
    parser.add_argument(
        "--final-blocks-only",
        action="store_true",
        help="only receive irreversible blocks, no BlockUndoSignal is ever sent",
    )
    parser.add_argument(
        "--cursor-file",
        default="data/cursor.txt",
        help="where the cursor is persisted (default: %(default)s)",
    )

    # argparse takes a negative start like `-1:` for an unknown flag, pick it back up here
    args, extra = parser.parse_known_args()
    negative_ranges = [arg for arg in extra if re.fullmatch(r"-\d+:.*", arg)]
    if len(negative_ranges) != len(extra) or (negative_ranges and args.block_range):
        parser.error(f"unrecognized arguments: {' '.join(extra)}")
    if negative_ranges:
        args.block_range = negative_ranges[0]

    if not args.endpoint:
        parser.error("endpoint is required (argument or SUBSTREAMS_ENDPOINT environment variable)")

    return args


def main() -> None:
    args = parse_args()

    args.api_key = os.getenv("SUBSTREAMS_API_KEY")
    if not args.api_key:
        sys.exit("Error: SUBSTREAMS_API_KEY environment variable is not defined.")

    try:
        package = read_package(args.spkg)
        if args.params:
            apply_params(package, parse_params(args.params))

        module = find_module(package, args.module)
        start, stop = parse_block_range(args.block_range, module.initial_block)
    except (ValueError, OSError, requests.RequestException) as err:
        sys.exit(f"Error: {err}")

    try:
        run(args, package, start, stop)
    except KeyboardInterrupt:
        log("Interrupted")


if __name__ == "__main__":
    main()
